const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const newMexico = ee.FeatureCollection('USGS/US_STATES').filter(ee.Filter.eq('NAME', 'New Mexico')).first().geometry();
    const startYear = 2000; // MODIS data starts around 2000
    const endYear = 2016;
    const targetYear = 2016;
    const startMonth = 7; // July
    const endMonth = 7;   // July
    const scale = 1000; // MODIS LST resolution is 1km

    // Function to mask clouds and scale LST
    const maskAndScaleLST = function(image) {
      // Select the LST_Day_1km band
      let lst = image.select('LST_Day_1km');
      // Scale LST to Kelvin
      lst = lst.multiply(0.02);

      // Get the Quality Control band
      const qc = image.select('QC_Day');

      // QC_Day bits breakdown:
      // Bit 0-1: LST quality (00 = good, 01 = good, 10 = questionable, 11 = bad)
      // Bit 2-3: Cloud state (00 = clear, 01 = cloudy, 10 = mixed, 11 = not set)
      // We want good quality (bits 0-1 < 2) and clear sky (bits 2-3 == 0)

      // Apply LST quality mask (bits 0-1)
      const lstQualityMask = qc.rightShift(0).mod(4).lt(2); // Keep 00 (good) and 01 (good)
      lst = lst.updateMask(lstQualityMask);

      // Apply cloud state mask (bits 2-3)
      const cloudStateMask = qc.rightShift(2).mod(4).eq(0); // Keep 00 (clear sky)
      lst = lst.updateMask(cloudStateMask);

      return lst.copyProperties(image, ['system:time_start', 'system:index']);
    };

    // Initialize lists to store mean LST values
    let targetYearLST = null;
    const comparisonYearsLSTs = [];

    for (let year = startYear; year <= endYear; year++) {
      const startDate = ee.Date.fromYMD(year, startMonth, 1);
      const endDate = ee.Date.fromYMD(year, endMonth, 31);

      // 2. Data Acquisition & Check
      let collection = ee.ImageCollection('MODIS/061/MOD11A2')
        .filterDate(startDate, endDate)
        .filterBounds(newMexico);

      const initialSize = collection.size().getInfo();
      if (initialSize === 0) {
        console.log(`No images found for July ${year}.`);
        if (year === targetYear) {
          console.log("C1");
          return;
        }
        continue;
      }

      // Apply masking and scaling
      collection = collection.map(maskAndScaleLST);

      // Reduce the collection to a single image by taking the mean for the month
      const meanLSTImage = collection.mean();

      if (meanLSTImage.bandNames().size().getInfo() === 0) {
        console.log(`No valid LST band after masking for July ${year}.`);
        if (year === targetYear) {
          console.log("C2"); // No valid pixels after masking
          return;
        }
        continue;
      }

      // Calculate the mean LST over New Mexico for the specific year and month
      const stats = meanLSTImage.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: newMexico,
        scale: scale,
        maxPixels: 1e9
      });

      const meanValue = stats.get('LST_Day_1km').getInfo();
      const pixelCount = meanLSTImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: newMexico,
        scale: scale,
        maxPixels: 1e9
      }).get('LST_Day_1km').getInfo();

      if (meanValue === null || isNaN(meanValue) || pixelCount === 0) {
        console.log(`Calculation failed or no valid pixels for July ${year}. Value: ${meanValue}, Pixels: ${pixelCount}`);
        if (year === targetYear) {
          console.log("C2"); // Treat null/NaN from reduction or 0 pixels as C2
          return;
        }
        continue;
      }

      const meanValueCelsius = meanValue - 273.15; // Convert Kelvin to Celsius
      console.log(`July ${year} LST (C): ${meanValueCelsius.toFixed(2)}, Valid Pixels: ${pixelCount}`);

      if (year === targetYear) {
        targetYearLST = meanValueCelsius;
      } else {
        comparisonYearsLSTs.push(meanValueCelsius);
      }
    }

    // 5. Validation & Final Answer
    if (targetYearLST === null) {
      console.log(`Target year ${targetYear} LST could not be calculated.`);
      console.log("C3");
      return;
    }

    if (comparisonYearsLSTs.length === 0) {
      console.log("No comparison data available for previous Julys.");
      console.log("C1");
      return;
    }

    const maxOtherJulyLST = Math.max(...comparisonYearsLSTs);

    console.log(`\nComparison:`);
    console.log(`July ${targetYear} Mean LST (C): ${targetYearLST.toFixed(2)}`);
    console.log(`Max Mean LST (C) in other Julys (${startYear}-${targetYear - 1}): ${maxOtherJulyLST.toFixed(2)}`);

    if (targetYearLST > maxOtherJulyLST) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (e) {
    console.error("An error occurred during analysis:", e);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
